const uint32_t BLOCK_DIM = 8;
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    NearestNeighborUpsampleCustomTilingData tiling;

    const gert::Shape* in_shape = context->GetInputShape(0);
    auto dims = in_shape->GetOriginShape().GetDims();
    // Expect NCHW
    uint32_t n = static_cast<uint32_t>(dims[0]);
    uint32_t c = static_cast<uint32_t>(dims[1]);
    uint32_t inH = static_cast<uint32_t>(dims[2]);
    uint32_t inW = static_cast<uint32_t>(dims[3]);

    const uint32_t scale = 4;
    uint32_t outH = inH * scale;
    uint32_t outW = inW * scale;

    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_inH(inH);
    tiling.set_inW(inW);
    tiling.set_scale(scale);
    tiling.set_outH(outH);
    tiling.set_outW(outW);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

